-- Townlong Steppes quest mobs that alexkulya's 5.4.8 core binds to a C++ script
-- (npc_seething_hatred, npc_korthik_timberhusk, npc_hei_feng, npc_suna_silentstrike).
-- These creatures had no spawn, so the kill objectives of "Hatred Becomes Us" (30783,
-- 8 x Seething Hatred 61054), "Up In Flames" (30973, 10 x Kor'thik Timberhusk 61355),
-- "Surprise Attack!" (31277, Hei Feng 63920) and "The Point of No Return" (30784,
-- Suna Silentstrike 61055) had no targets. The scripts only add combat casts, so the
-- quests work once the mobs exist and are hostile. This adds alexkulya's 50 spawns (same
-- guids, default phase) and sets the hostile factions from alexkulya's templates: 61054
-- and 61092 (the second Seething Hatred template, same name) faction 16, 61355 faction
-- 2558, 61055 faction 14 (Hei Feng is already faction 7). Suna's script also keeps Suna
-- alive and gives the credit on a would-be killing blow; here she dies normally and the
-- kill gives the same credit.
-- Before this update no creature rows existed for 61054, 61092, 61355, 63920 and 61055,
-- and templates 61054, 61092, 61355 and 61055 had faction 35/35.
DELETE FROM `creature` WHERE `guid` IN (521619,522574,522575,522576,522577,522578,522579,522595,522611,522612,522613,522614,522615,522616,522617,522597,522598,522599,522600,522601,522609,522610,522620,522621,522622,523540,523541,523542,523543,523544,523545,523546,523547,523548,523549,523550,523551,523552,523553,523554,523555,523556,523557,523558,523559,523560,523561,523573,523574,524216);

UPDATE `creature_template` SET `faction_A` = 16, `faction_H` = 16 WHERE `entry` IN (61054, 61092);
UPDATE `creature_template` SET `faction_A` = 2558, `faction_H` = 2558 WHERE `entry` = 61355;
UPDATE `creature_template` SET `faction_A` = 14, `faction_H` = 14 WHERE `entry` = 61055;
